          "level_type": "INFO_LEVEL",
          "estimated_duration": 0,
          "order": 7,
          "content": "**Congratulation.** Thanks to the cracked private key, you connected to the other server with SSH and found a file there with the following content:\n\n\n\n```\nYou have found us, as we wanted you to. We are not what most say. We know things that the top 1% of the top 1% do not want us to know. We need recruits for fighting against them. We have chosen you. \n\nWe are the future. \n\nExpect us to be contacting you soon. \n\n**▒░░░░░░|<0by1k/\\\\░3302░▒** \n\nEpstein did not kill himself.\n```\n\n---\n\nCredits: [storyline inspiration](https://en.wikipedia.org/wiki/Cicada_3301)\n\nMade by students of the *Seminar on Simulation of Cyber Attacks* course in December 2019."
